"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[6151],{5184(e){e.exports=JSON.parse('{"title":"Combobox\uc640 \uce5c\uad6c\ub4e4, \uc5b4\ub5a4 \uac83\uc744 \uc120\ud0dd\ud574\uc57c \ud558\ub294\uac00","date":"2026-02-13","coverUrl":"/kudzu-based-bench/assets/notion/3e8c4b1b81c7374c.png","html":"<h1 data-notion-block-id=\\"301e548d-8a8e-805b-b01f-c0ba0e0ac4ad\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"304e548d-8a8e-8082-9457-e5a4e4293d65\\" id=\\"304e548d-8a8e-8082-9457-e5a4e4293d65\\">Combobox\uc640 \uce5c\uad6c\ub4e4, \uc5b4\ub5a4 \uac83\uc744 \uc120\ud0dd\ud574\uc57c \ud558\ub294\uac00</h2><a href=\\"https://www.smashingmagazine.com/2026/02/combobox-vs-multiselect-vs-listbox/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.smashingmagazine.com/2026/02/combobox-vs-multiselect-vs-listbox/</a><p data-notion-block-id=\\"304e548d-8a8e-8014-9a7e-c52947c0f69e\\">Combobox/MultiSelect/Listbox\ub294 \ube44\uc2b7\ud55c UI \uad6c\uc870\ub97c \uac00\uc84c\uace0, \uadf8\ub807\uae30\uc5d0 \uc5b4\ub5a8 \ub54c \uc5b4\ub5a4 UI \ud328\ud134\uc744 \uc120\ud0dd\ud574\uc57c \ud558\ub294\uc9c0 \ud56d\uc0c1 \uace0\ubbfc\uc774 \ub418\ub294 \ubd80\ubd84\uc785\ub2c8\ub2e4. \uadf8 \ucc28\uc774\ub97c \uc54c\uc544\ubcf4\uace0 \uc120\ud0dd \uae30\uc900\uc744 \uc57d\uac04 \uc54c\ub824\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\uc678\uc5d0\ub3c4 OpenUI\uc758 <a href=\\"https://open-ui.org/components/combobox.explainer/\\">Combobox\ub97c \uc5b4\ub5bb\uac8c \ud45c\uc900\uc5d0 \ub9de\uac8c \uad6c\ud604\ud560\uae4c</a>\uc640 React Aria\uc758 <a href=\\"https://react-aria.adobe.com/blog/building-a-combobox\\">Combobox autocomplete \uac1c\uc120\uae30</a>\ub3c4 \uac19\uc774 \ubcf4\uc2dc\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"304e548d-8a8e-8075-b819-ce73b9faadcf\\" id=\\"304e548d-8a8e-8075-b819-ce73b9faadcf\\">Breakpoint\uc744 rough\ud558\uac8c \uc7a1\uc73c\uba74 \uc0ac\uc6a9\uc790 \uacbd\ud5d8\uc744 \ud574\uce60 \uc218\ub3c4 \uc788\ub2e4.</h2><a href=\\"https://ishadeed.com/article/too-early-breakpoint/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ishadeed.com/article/too-early-breakpoint/</a><p data-notion-block-id=\\"301e548d-8a8e-8077-b397-d265d84fd94d\\">\uc77c\ubc18\uc801\uc778 mobile / tablet breakpoint\uc774 \uc788\uace0, \uc774\ub97c \ub530\ub974\ub294 \uacbd\ud5a5\uc774 \uc788\uc9c0\ub9cc \uc5ec\ub7ec \ubc29\uba74\uc758 \uc6f9\ud398\uc774\uc9c0 \ud658\uacbd\uc5d0\uc11c \ubd88\ud3b8\ud55c \uacbd\ud5d8\uc744 \ud560 \uc218\ub3c4 \uc788\ub2e4\ub294 \uc758\uacac\uc758 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/29ce548d-8a8e-8067-9bb1-df4bcee7abbb#29ce548d-8a8e-8057-8f34-c6a9f4ada139\\">\uc139\uc158 \ub808\uc774\uc544\uc6c3 \ub354\uc6b1\ub354 \ubc18\uc751\ud615\uc73c\ub85c \ub9cc\ub4e4\uae30</a> \uc544\ud2f0\ud074\uc5d0\uc11c\ub3c4 \ubcfc \uc218 \uc788\ub4ef\uc774, \ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c\uc758 CSS\ub294 JS \uc5c6\uc774\ub3c4 \uc5ec\ub7ec \ubc18\uc751\ud615 \ub808\uc774\uc544\uc6c3\uc744 \ub9cc\ub4e4 \uc218 \uc788\uc73c\ubbc0\ub85c, container queries\ubd80\ud130 \uc2dc\uc791\ud574\uc11c \ub2e4\uc591\ud55c selector \uc870\ud569\uc744 \uc798 \uc54c\uace0 \uc788\uc73c\uba74 \uc88b\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"301e548d-8a8e-802c-af4d-e98da8bff680\\" id=\\"301e548d-8a8e-802c-af4d-e98da8bff680\\">Next.js\uc5d0\uc11c Tanstack Start\ub85c \ubc14\uafe8\ub2e4. \uadf8 \uc774\uc720\ub294..(\ub354 \ubcf4\uae30)</h2><a href=\\"https://www.inngest.com/blog/migrating-off-nextjs-tanstack-start\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.inngest.com/blog/migrating-off-nextjs-tanstack-start</a><p data-notion-block-id=\\"304e548d-8a8e-80bd-8458-cdc1028af26b\\">\uac04\ub2e8\ud558\uac8c\ub9cc \ubcf4\uba74 Next.js\uc758 RSC, \uadf8\ub9ac\uace0 \uc11c\ubc84/\ud074\ub77c\uc774\uc5b8\ud2b8 \uacbd\uacc4\uc758 \ubaa8\ud638\ud568\uc758 \ub2e8\uc810\uc744 \ud06c\uac8c \uc0dd\uac01\ud574\uc11c Next.js\uc640 Tanstack Start\ub9cc \ube44\uad50\ud558\uace0 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uacfc\uc815\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc774\uc9c0\ub9cc, \uae00\uc758 \ub9c8\uc9c0\ub9c9\uc5d0 \ub9ce\uc740 \uac83\uc744 \uace0\ub824\ud588\uace0, \uc5b4\ub5a4 \uad50\ud6c8\uc744 \uc5bb\uac8c \ub418\uc5c8\ub294\uc9c0 \uc18c\uac1c\ud558\ubbc0\ub85c \ub9c8\uc9c0\ub9c9\uc758 \uad50\ud6c8 \uae00\uacfc \uadf8\ub9bc\uc744 \uaf2d \ubcf4\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"301e548d-8a8e-80bb-ad17-c33d084af955\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"304e548d-8a8e-8004-8e2e-ecd711664c16\\" id=\\"304e548d-8a8e-8004-8e2e-ecd711664c16\\">\ud074\ub798\uc2a4 \uae30\ubc18 \uac1d\uccb4\ub294 \uc65c React Compiler\uc5d0 \ubc18\ud558\ub294\uac00</h2><a href=\\"https://anita-app.com/blog/articles/react-compiler-and-why-class-objects-work-against-memoization.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://anita-app.com/blog/articles/react-compiler-and-why-class-objects-work-against-memoization.html</a><p data-notion-block-id=\\"304e548d-8a8e-8056-8da9-c453acf87d68\\">\ud074\ub798\uc2a4 \uae30\ubc18 \uac1d\uccb4\ub294 React Compiler\uc758 \uba54\ubaa8\uc774\uc81c\uc774\uc158 \uc804\ub7b5\uacfc \uc65c \ubc18\ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"301e548d-8a8e-80fc-804f-c5eb86f8451e\\" id=\\"301e548d-8a8e-80fc-804f-c5eb86f8451e\\">AI\uac00 \ub514\ubc84\uae45\uc744 \uc0ac\ub78c\ubcf4\ub2e4 \uc798\ud560\uae4c?</h2><a href=\\"https://www.developerway.com/posts/debugging-with-ai\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.developerway.com/posts/debugging-with-ai</a><p data-notion-block-id=\\"304e548d-8a8e-8056-8657-ff6189534bfd\\">\uc138\uac00\uc9c0 \ub514\ubc84\uae45 \uc0ac\ub840\uc5d0\uc11c AI\ub97c \uc0ac\uc6a9\ud574\ubcf4\uace0, \uc798 \ud574\uacb0\ud588\ub294\uc9c0/\uc6d0\uc778\ud30c\uc545\uc744 \uc798 \ud588\ub294\uc9c0/\uc62c\ubc14\ub978 \uadfc\ubcf8 \ud574\uacb0\ud588\ub294\uc9c0\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. MCP\ud65c\uc6a9 \ub2a5\ub825/\ud504\ub86c\ud3ec\ud305 \ub2a5\ub825/Agent \ud65c\uc6a9 \ub2a5\ub825\uc5d0 \ub530\ub77c AI\uc640 \ud568\uaed8 \ub514\ubc84\uae45\ud558\ub294 \ub2a5\ub825\uc774 \ub298\uc5b4\ub098\uaca0\uc9c0\ub9cc, \uac1c\ubc1c\uc790\uc758 \ub113\uac8c \ubcf4\ub294 \ub2a5\ub825, \ub610\ud55c \ud504\ub808\uc784\uc6cc\ud06c \uc774\ud574 \ub2a5\ub825\uc774 \ud544\uc694\ud574\ubcf4\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"301e548d-8a8e-802e-b215-c8896b14689a\\" id=\\"301e548d-8a8e-802e-b215-c8896b14689a\\">Node.js 7\uc5d0\uc11c \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc744 \ud574\ub0c8\ub2e4</h2><a href=\\"https://remysharp.com/2026/02/02/js-bin-down-in-2026\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://remysharp.com/2026/02/02/js-bin-down-in-2026</a><p data-notion-block-id=\\"304e548d-8a8e-809b-9b3f-e9a6df2be0b1\\">Node.js\uc758 \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc744 LLM\uc758 \ub3c4\uc6c0\uc744 \ubc1b\uc544\uc11c \ud574\ub0c8\uace0, \uadf8\uc640 \ube44\uc2b7\ud558\uac8c \ud504\ub860\ud2b8\uc5d4\ub4dc \uc778\ud504\ub77c \uac1c\uc120\ud558\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"304e548d-8a8e-80f5-9e88-dfbae861a839\\" id=\\"304e548d-8a8e-80f5-9e88-dfbae861a839\\">Shrinkwrap \ubb38\uc81c \ud574\uacb0 \ubc29\ubc95</h2><a href=\\"https://kizu.dev/shrinkwrap-solution/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://kizu.dev/shrinkwrap-solution/</a><p data-notion-block-id=\\"304e548d-8a8e-80df-bbd2-e1690136cfc3\\">\ud14d\uc2a4\ud2b8\uac00 \uc5ec\ub7ec \uc904\ub85c \uc904\ubc14\uafc8\ub420 \ub54c \ucee8\ud14c\uc774\ub108 \uc694\uc18c\uc5d0 \ubd88\ud544\uc694\ud55c \uacf5\ubc31\uc774 \uc0dd\uae30\ub294 Shrinkwrap \ubb38\uc81c\ub97c \ucd5c\uc2e0 CSS(\uc544\uc9c1 \ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800 \uc804\uccb4\uc5d0 \uc801\uc6a9\ub418\uc9c0\ub294 \uc54a\uc74c)\ub85c \uc5b4\ub5bb\uac8c \ud574\uacb0\ud558\ub294\uac00\uc5d0 \ub300\ud55c \uae00\uc785\ub2c8\ub2e4. \uc65c \uc774\ub7f0 \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud558\ub294\uc9c0\ub294 \uc774\uc804 \uae00\uc778 <a href=\\"https://kizu.dev/shrinkwrap-problem/\\">Shrinkwrap \ubb38\uc81c \uc815\uc758 \ubc0f Anchor positioning \uc18c\uac1c</a> \uae00\uc744 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"301e548d-8a8e-80b8-95e7-ee9732067487\\" id=\\"301e548d-8a8e-80b8-95e7-ee9732067487\\">\uc811\uadfc\uc131 \ub514\uc790\uc774\ub108\uc758 \ud0a4\ubcf4\ub4dc \ub2e8\ucd95\ud0a4 \ucd94\uac00 \uc2dc \uace0\ub824\uc0ac\ud56d</h2><a href=\\"https://ericwbailey.website/published/how-an-accessibility-designer-adds-keyboard-shortcuts-to-a-web-app/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ericwbailey.website/published/how-an-accessibility-designer-adds-keyboard-shortcuts-to-a-web-app/</a><h2 data-notion-block-id=\\"301e548d-8a8e-801c-94b9-d290d0ec524e\\" id=\\"301e548d-8a8e-801c-94b9-d290d0ec524e\\">JS \uc5c6\uc774 Video Embed \ucd5c\uc801\ud654\ud558\uae30</h2><a href=\\"https://frontendmasters.com/blog/performance-optimized-video-embeds-with-zero-javascript/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/performance-optimized-video-embeds-with-zero-javascript/</a><p data-notion-block-id=\\"304e548d-8a8e-8048-bb4e-e08c1e9f4dda\\">JS \uc5c6\uc774 Video Thumbnail\uc744 \ubcf4\uc5ec\uc8fc\uace0 \ud074\ub9ad\ud558\uba74 Video Embed\ub97c \ubcf4\uc5ec\uc8fc\ub294 \ubc29\uc2dd\uc744 \uc5b4\ub5bb\uac8c \uad6c\ud604\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"301e548d-8a8e-80c4-921d-d6b95f2fee48\\" id=\\"301e548d-8a8e-80c4-921d-d6b95f2fee48\\">State of JS 2025 \uc124\ubb38\uc870\uc0ac</h2><a href=\\"https://2025.stateofjs.com/ko-KR/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://2025.stateofjs.com/ko-KR/</a><h1 data-notion-block-id=\\"301e548d-8a8e-801b-af9e-d7832c2c6c2e\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://nodejs.org/en/blog/migrations/chalk-to-styletext\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nodejs.org/en/blog/migrations/chalk-to-styletext</a><p data-notion-block-id=\\"301e548d-8a8e-8038-b16a-c99baf80b194\\">CLI\uc744 \ub9cc\ub4e4 \ub54c \ub9ce\uc774 \uc0ac\uc6a9\ud558\ub294 Chalk \ub300\uc2e0 Node.js\uc5d0\uc11c\uc758 \ub124\uc774\ud2f0\ube0c\ub85c \uc9c0\uc6d0\ud558\ub294 styleText\ub97c \uc0ac\uc6a9\ud558\ub294 \uac83\uc744 \uad8c\ud558\uace0, \uc5b4\ub5bb\uac8c \ubc14\uafb8\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://www.sanity.io/blog/the-logo-soup-problem\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.sanity.io/blog/the-logo-soup-problem</a><p data-notion-block-id=\\"301e548d-8a8e-808d-a7cb-d51a693ab41a\\">logo svg\ub098 \uc774\ubbf8\uc9c0\ub97c \uc0ac\uc6a9\ud560 \uacbd\uc6b0\uc5d0 \uc5b4\ub5a4 \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud558\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c \uc774\ub97c \ud574\uacb0\ud588\ub294\uc9c0(\uadf8\ub9ac\uace0 \uc774\ub97c \ub77c\uc774\ube0c\ub7ec\ub9ac\ub85c \ub9cc\ub4e4\uc5b4\uc11c) \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://babeljs.io/blog/2026/01/31/7.29.0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://babeljs.io/blog/2026/01/31/7.29.0</a><p data-notion-block-id=\\"301e548d-8a8e-8049-8f10-ebd0770586c2\\">Babel 8\uc5d0\uc11c require(esm)\uc744 \uc9c0\uc6d0\ud558\uae30 \uc704\ud574 \uc9c0\uc6d0\ud558\ub294 Node.js\ubc84\uc804\uacfc ESM-only \ud328\ud0a4\uc9c0\ub85c \uc804\ud658\ud55c\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://www.gatsbyjs.com/docs/reference/release-notes/v5.16/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.gatsbyjs.com/docs/reference/release-notes/v5.16/</a><p data-notion-block-id=\\"301e548d-8a8e-80e6-8c45-d6b525ae3b2e\\">Gatsby\uac00 \uc778\uc218\ub418\uace0\ub098\uc11c \uad00\ub9ac\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \ub9d0\uc774 \ub9ce\uc558\uc9c0\ub9cc, 5.16\ubc84\uc804\uc744 \ucd9c\uc2dc\ud558\uba74\uc11c \uc0b4\uc544\uc788\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc8fc\uace0 \uc788\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://www.repoflow.io/blog/node-js-16-to-25-benchmarks-how-performance-evolved-over-time\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.repoflow.io/blog/node-js-16-to-25-benchmarks-how-performance-evolved-over-time</a><p data-notion-block-id=\\"301e548d-8a8e-8092-9260-f04cb7525f17\\">Node.js 16\ubd80\ud130 25\uae4c\uc9c0\uc758 \uc5ec\ub7ec \uc131\ub2a5\uc744 \ube44\uad50\ud55c \ubca4\uce58\ub9c8\ud06c\ub97c \uc18c\uac1c\ud558\ub294  \uae00\uc785\ub2c8\ub2e4.</p>"}')}}]);